import type { UnitQuestion, UnitTemplate } from "./unit-seeds.js";
import { sourceByGrade } from "./unit-seeds-v2-expanded.js";

type Role = "oliver" | "ruby" | "marcus";
type Beat = UnitTemplate["scene"][number];
const b = (speaker: Beat["speaker"], english: string, chinese: string): Beat => ({ speaker, english, chinese });
const q = (kind: UnitQuestion["kind"], prompt: string, answer: string,
  options: string[], explanation: string, acceptedAnswers?: string[]): UnitQuestion =>
  ({ kind, prompt, answer, options, explanation, acceptedAnswers, id: "" });

// 精确匹配短写的等价表达。逐单元指定，避免把某个词的同义词套用到其他语境。
const writeVariants: Readonly<Record<string, readonly string[]>> = {
  "unit-v3-oliver-g8-1": ["maps in the book"],
  "unit-v3-ruby-g8-1": ["3 hours"],
  "unit-v3-marcus-g8-1": ["the boy's feelings"],
  "unit-v3-oliver-g9-1": ["not the opening"],
  "unit-v3-ruby-g9-1": ["shared beaches", "beaches surveyed twice"],
  "unit-v3-marcus-g9-1": ["15 years"],
  "unit-v3-oliver-g10-1": ["move the opening back fifteen minutes"],
  "unit-v3-ruby-g10-1": ["small groups with a guide"],
  "unit-v3-marcus-g10-1": ["cropped to protect the child"],
  "unit-v3-oliver-g11-1": ["new feedback from teen readers"],
  "unit-v3-ruby-g11-1": ["guessing why food was left"],
  "unit-v3-marcus-g11-1": ["inferring her feelings from posture"],
  "unit-v3-oliver-g12-1": ["track jams and costs before signing"],
  "unit-v3-ruby-g12-1": ["check western beaches before expanding restrictions"],
  "unit-v3-marcus-g12-1": ["test with screen reader users and revise"],
  "unit-v3-oliver-g8-2": ["confirm whether you can attend Sunday"],
  "unit-v3-ruby-g8-2": ["redirect visitors at the beach sign"],
  "unit-v3-marcus-g8-2": ["once you know the camera controls"],
  "unit-v3-oliver-g9-2": ["our copy with archive records"],
  "unit-v3-ruby-g9-2": ["report when the team returns"],
  "unit-v3-marcus-g9-2": ["given the wrong date"],
  "unit-v3-oliver-g10-2": ["we confirm who owns it"],
  "unit-v3-ruby-g10-2": ["moved visitors back from the path"],
  "unit-v3-marcus-g10-2": ["a safer margin for transfers"],
  "unit-v3-oliver-g11-2": ["family story sharing evening"],
  "unit-v3-ruby-g11-2": ["clear directions in a quiet place"],
  "unit-v3-marcus-g11-2": ["mark all digitally invented details"],
  "unit-v3-oliver-g12-2": ["the visitor has already departed"],
  "unit-v3-ruby-g12-2": ["a moving image rather than evidence"],
  "unit-v3-marcus-g12-2": ["matching environmental data from both suppliers"],
};
const unit = (role: Role, grade: number, slot: number, sourceIndex: number, title: string,
  objective: string, scene: Beat[], questions: UnitQuestion[]): UnitTemplate => {
  if (questions.length !== 6) throw new Error(`单元必须有六道逐题编写的题目：${title}`);
  const learningReference = sourceByGrade[grade]?.[sourceIndex];
  if (!learningReference) throw new Error(`缺少教材参考：${title}`);
  const id = `unit-v3-${role}-g${String(grade)}-${String(slot)}`;
  return { id, roleKey: role, grade, title, objective,
    learningReference, scene, questions: questions.map((question, index) => ({
      ...question, id: `q${String(index + 1)}`,
      acceptedAnswers: question.kind === "write" ? writeVariants[id] ?? question.acceptedAnswers : undefined,
    })) };
};

